#include <stdio.h>

#define MAXN 100005

int stack[MAXN];

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int top = 0;
    for (int i = 0; i < n; i++) {
        int x;
        scanf("%d", &x);
        if (x == 0) {
            if (top > 0) {
                top--;
            }
        } else {
            stack[top++] = x;
        }
    }

    long long sum = 0;
    for (int i = 0; i < top; i++) {
        sum += stack[i];
    }

    printf("%lld\n", sum);

    return 0;
}
